def _client():
    key = os.environ.get('OPENAI_API_KEY')
    if not key:
        raise ValueError("OPENAI_API_KEY environment variable not set")
    return OpenAI(api_key=key)

def _fetch(url):
    r = httpx.get(url, timeout=120, follow_redirects=True)
    r.raise_for_status()
    return Image.open(io.BytesIO(r.content)).convert('RGB')

def _gen_item_image(piece, client):
    """E-commerce product photography ÃÂÃÂÃÂÃÂ¢ÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ clean white background, no AI gloss."""
    col  = _color_name(piece.get('color', '#888888'))
    mat  = piece.get('material', '')
    name = piece.get('name', 'clothing item')
    mat_str = f"{mat} " if mat else ""
    prompt = (
        f"Flat lay product photo on a pure white surface. A single {col} {mat_str}{name} "
        f"placed flat on a white background, photographed from directly above. "
        f"Clean and minimal: just the garment lying flat on white, nothing else. "
        f"No people, no mannequins, no hangers, no studio equipment, no lighting stands, "
        f"no backdrops, no props, no shadows, no brand logos, no text. "
        f"Natural fabric texture: matte fabrics look matte, suede looks like suede, leather shows grain. "
        f"Photorealistic, 8K detail, e-commerce flat-lay style."
    )
    resp = client.images.generate(
        model="dall-e-3", prompt=prompt,
        size="1024x1024", quality="hd", n=1
    )
    return _fetch(resp.data[0].url)

def _gen_look_image(outfit, context, weather, client):
    """Portrait using Gemini (Nano Banana) with DALL-E-3 fallback."""
    pieces = outfit.get('pieces', [])
    descs  = []
    for p in pieces:
        col   = p.get('color_name', '') or _color_name(p.get('color', '#888888'))
        name  = p.get('name', '')
        brand = p.get('brand', '')
        entry = f"{col} {name}".strip()
        if brand:
            entry += f" ({brand})"
        descs.append(entry)
    outfit_str = ", ".join(descs) if descs else "casual outfit"

    prompt = (
        f"Full-body fashion portrait of ONE man, single person only. "
        f"COMPLETE HEAD-TO-TOE shot — top of head down to shoes, full figure in frame. "
        f"He is wearing ALL of these pieces simultaneously as one coordinated outfit: {outfit_str}. "
        f"Clean off-white studio background. Relaxed confident posture, slight smile, facing camera. "
        f"Sharp aspirational menswear — well put-together, fashion-forward. "
        f"Short brown hair, green eyes, lean athletic build, mid-30s. "
        f"Soft studio lighting, natural fabric drape. Photorealistic, magazine quality."
    )

    gemini_key = os.environ.get('GEMINI_API_KEY', '')
    if gemini_key and _ggenai is not None:
        try:
            gclient = _ggenai.Client(api_key=gemini_key)
            response = gclient.models.generate_images(
                model='imagen-3.0-generate-002',
                prompt=prompt,
                config=_gtypes.GenerateImagesConfig(
                    number_of_images=1,
                    aspect_ratio='9:16',
                    person_generation='allow_adult',
                    safety_filter_level='block_some',
                )
            )
            img_bytes = response.generated_images[0].image.image_bytes
            return Image.open(io.BytesIO(img_bytes)).convert('RGB')
        except Exception as e:
            print(f'[gemini-portrait] failed: {e}, falling back to DALL-E')

    # Fallback: DALL-E-3
    resp = client.images.generate(
        model="dall-e-3", prompt=prompt,
        size="1024x1792", quality="hd", n=1
    )
    return _fetch(resp.data[0].url)

def _load_all_images(outfit, context, weather):
    """Fetch item images from URLs (DALL-E fallback) + generate portrait."""
    c = _client()
    ACC_CATS = {'ACCESSORIES', 'BELT', 'SCARF', 'WATCH'}
    pieces = [p for p in outfit.get('pieces', [])
              if p.get('category', '').upper() not in ACC_CATS][:4]

    def fetch_piece(piece):
        url = piece.get('image_url')
        if url:
            try:
                r = httpx.get(url, timeout=30, follow_redirects=True)
                r.raise_for_status()
                return Image.open(io.BytesIO(r.content)).convert('RGB')
            except Exception as e:
                print(f'[warn] item fetch failed: {e}')
        return _gen_item_image(piece, c)

    results = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=5) as ex:
        item_futs = {ex.submit(fetch_piece, p): i for i, p in enumerate(pieces)}
        look_fut  = ex.submit(_gen_look_image, outfit, context, weather, c)

        for fut, idx in item_futs.items():
            try:
                results[f'item_{idx}'] = fut.result(timeout=60)
            except Exception as e:
                print(f'[warn] item {idx}: {e}')
                results[f'item_{idx}'] = Image.new('RGB', (400, 400),
                    _hex_rgb(pieces[idx].get('color', '#999999')))
        try:
            results['look'] = look_fut.result(timeout=120)
        except Exception as e:
            print(f'[warn] portrait failed: {e}')
            results['look'] = None

    item_imgs = [results.get(f'item_{i}', Image.new('RGB', (400, 400), (200, 200, 200)))
                 for i in range(len(pieces))]
    return pieces, item_imgs, results.get('look')


# Ã¢ÂÂÃ¢ÂÂ HTML Card Builder Ã¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂ
def _img_to_b64(img: Image.Image) -> str:
    """Convert PIL Image to embedded JPEG data URI."""
    buf = io.BytesIO()
    img.convert('RGB').save(buf, format='JPEG', quality=88)
    return 'data:image/jpeg;base64,' + base64.b64encode(buf.getvalue()).decode()


def _build_card_html(pieces, item_imgs, look_img, stylist_note: str) -> str:
    """Render outfit card as HTML string with base64-embedded images."""

    # Item cells (2x2 grid)
    cells_html = ''
    for piece, img in zip(pieces, item_imgs):
        b64        = _img_to_b64(img)
        name       = piece.get('name', '')
        brand      = piece.get('brand', '')
        color_name = (piece.get('color_name', '') or '').title()
        brand_line = f"{color_name} \u00b7 {brand}" if color_name and brand else brand
        cells_html += f"""
        <div class="cell">
          <div class="cell-img"><img src="{b64}" alt="{name}"></div>
          <div class="cell-text">
            <div class="cell-name">{name}</div>
            <div class="cell-brand">{brand_line}</div>
          </div>
        </div>"""

    # Portrait
    if look_img:
        port_b64     = _img_to_b64(look_img)
        portrait_tag = f'<img class="portrait" src="{port_b64}" alt="outfit">'
    else:
        portrait_tag = '<div class="portrait" style="background:#EDEBE5;"></div>'

    note_safe = (stylist_note
                 .replace('&', '&amp;')
                 .replace('<', '&lt;')
                 .replace('>', '&gt;'))

    return f"""<!DOCTYPE html>
<html><head><meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&family=Playfair+Display:ital@1&display=swap" rel="stylesheet">
<style>
* {{ margin:0; padding:0; box-sizing:border-box; }}
body {{
  width: 800px;
  background: #FAFAF8;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  padding: 36px 40px 48px;
}}
.top {{ display:flex; gap:20px; margin-bottom:32px; }}
.grid {{ display:grid; grid-template-columns:1fr 1fr; gap:14px; width:368px; flex-shrink:0; }}
.cell {{ background:#EDEBE5; border-radius:12px; overflow:hidden; }}
.cell-img {{ background:#fff; padding:10px; }}
.cell-img img {{ width:100%; height:188px; object-fit:contain; display:block; }}
.cell-text {{ padding:11px 13px 15px; }}
.cell-name {{ font-size:15px; font-weight:700; color:#111111; line-height:1.3; }}
.cell-brand {{ font-size:12px; color:#7A7068; margin-top:5px; font-weight:400; }}
.portrait-col {{ flex:1; min-width:0; }}
.portrait {{
  width:100%; height:100%; max-height:640px;
  object-fit:cover; object-position:top center;
  border-radius:12px; display:block;
}}
hr {{ border:none; border-top:1.5px solid #D5CEC8; margin-bottom:24px; }}
.tip-label {{
  font-size:13px; font-weight:700; letter-spacing:3px;
  color:#8B7355; text-transform:uppercase; margin-bottom:18px;
}}
.tip-text {{
  font-family:'Inter',-apple-system,sans-serif;
  font-size:17px; line-height:1.8; color:#2A2A2A; font-weight:400;
}}
</style>
</head><body>
  <div class="top">
    <div class="grid">{cells_html}</div>
    <div class="portrait-col">{portrait_tag}</div>
  </div>
  <hr>
  <div class="tip-label">STYLIST TIP</div>
  <div class="tip-text">{note_safe}</div>
</body></html>"""


# Ã¢ÂÂÃ¢ÂÂ Card Generator (HTML Ã¢ÂÂ Playwright Ã¢ÂÂ PNG) Ã¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂÃ¢ÂÂ
def generate_card(weather: dict, outfit: dict, output_path: str, context: str = "office") -> str:
    """
    Claudio Card v7 Ã¢ÂÂ HTML renderer.
    Generates card as HTML, screenshots with Playwright Chromium Ã¢ÂÂ PNG.
    """
    pieces, item_imgs, look_img = _load_all_images(outfit, context, weather)
    stylist_note = outfit.get('stylist_note', outfit.get('note', ''))
    html         = _build_card_html(pieces, item_imgs, look_img, stylist_note)

    from playwright.sync_api import sync_playwright
    with sync_playwright() as pw:
        browser = pw.chromium.launch(
            args=['--no-sandbox', '--disable-setuid-sandbox',
                  '--disable-dev-shm-usage', '--disable-gpu']
        )
        page = browser.new_page(viewport={'width': 800, 'height': 200})
        page.set_content(html, wait_until='networkidle', timeout=15000)
        page.screenshot(path=output_path, full_page=True)
        browser.close()

    return output_path
